<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/functions.php';require_login();$page_title='Members';$error='';
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE member_id=? AND status='Borrowed'");$q->execute([$id]);if((int)$q->fetchColumn()){flash('Member has active loans and cannot be deleted.','warning');}else{try{$q=$pdo->prepare("DELETE FROM members WHERE id=?");$q->execute([$id]);flash('Member deleted.');}catch(PDOException $e){flash('Unable to delete this member.','danger');}}header('Location: '.app_url('modules/members/index.php'));exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$num=trim($_POST['member_number']??'');$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$type=$_POST['member_type']??'Student';if($num===''||$name===''){$error='Member number and full name are required.';}else{try{$q=$pdo->prepare("INSERT INTO members(member_number,full_name,email,phone,member_type,registration_date) VALUES(?,?,?,?,?,CURDATE())");$q->execute([$num,$name,$email?:null,$phone?:null,in_array($type,['Student','Staff','External'])?$type:'Student']);flash('Member registered.');header('Location: '.app_url('modules/members/index.php'));exit;}catch(PDOException $e){$error='Member number or email already exists, or the record could not be saved.';}}}
$search=trim($_GET['q']??'');$sql="SELECT * FROM members";$params=[];if($search!==''){$sql.=" WHERE member_number LIKE ? OR full_name LIKE ? OR phone LIKE ?";$like="%$search%";$params=[$like,$like,$like];}$sql.=" ORDER BY id DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();require __DIR__.'/../../includes/header.php';?>
<div class="row"><div class="col-md-4"><div class="card card-primary"><div class="card-header"><h3 class="card-title">Register Member</h3></div><form method="post"><div class="card-body"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-group"><label>Member Number *</label><input name="member_number" class="form-control" required></div><div class="form-group"><label>Full Name *</label><input name="full_name" class="form-control" required></div><div class="form-group"><label>Email</label><input name="email" type="email" class="form-control"></div><div class="form-group"><label>Phone</label><input name="phone" class="form-control"></div><div class="form-group"><label>Member Type</label><select name="member_type" class="form-control"><option>Student</option><option>Staff</option><option>External</option></select></div></div><div class="card-footer"><button class="btn btn-primary">Register Member</button></div></form></div></div>
<div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">Registered Members</h3></div><div class="card-body"><form class="form-inline mb-3"><input name="q" value="<?=e($search)?>" class="form-control mr-2" placeholder="Search name, member no., phone"><button class="btn btn-secondary">Search</button></form><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>No.</th><th>Member</th><th>Contact</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['member_number'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?><br><?=e($r['phone'])?></td><td><?=e($r['member_type'])?></td><td><span class="badge badge-<?= $r['status']==='Active'?'success':'secondary'?>"><?=e($r['status'])?></span></td><td><a href="?delete=<?=(int)$r['id']?>" class="btn btn-danger btn-sm" onclick="return confirm('Delete member?')">Delete</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center">No members found.</td></tr><?php endif;?></tbody></table></div></div></div></div></div>
<?php require __DIR__.'/../../includes/footer.php';?>
